(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.RepoGrowthAnalytics=factory()})(globalThis,function(){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:0}),rate=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2});
const date=at=>new Date(at).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'});
function metric(n,label){return `<div class="metric"><strong>${count(n)}</strong><span>${esc(label)}</span></div>`}
function chart(points,key,label){
 if(points.length<2)return '<p class="chart-empty">Two saved observations are needed for a chart.</p>';
 const values=points.map(p=>p[key]),min=Math.min(...values),max=Math.max(...values),range=max-min||1,start=Date.parse(points[0].at),span=Date.parse(points.at(-1).at)-start||1;
 const xy=points.map(p=>[30+(Date.parse(p.at)-start)/span*640,145-(p[key]-min)/range*110]);
 return `<svg viewBox="0 0 700 175" role="img" aria-label="${esc(label)}: ${count(values[0])} to ${count(values.at(-1))}"><path d="M30 145H670" stroke="var(--line)"/><polyline fill="none" stroke="var(--lime)" stroke-width="3" stroke-linejoin="round" points="${xy.map(p=>p.join(',')).join(' ')}"/>${xy.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="var(--lime)"><title>${esc(points[i].at)}: ${count(values[i])}</title></circle>`).join('')}</svg><div class="chart-axis"><span>${esc(date(points[0].at))} · ${count(values[0])}</span><span>${esc(date(points.at(-1).at))} · ${count(values.at(-1))}</span></div>`;
}
function project(r,index){return `<details class="growth-project"><summary><span class="growth-project-title"><span class="growth-rank">${index+1}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.id)}</small></span></span><span>+${rate(r.starsPerDay)} stars/day</span><span>+${rate(r.forksPerDay)} forks/day</span><span>${rate(r.days)} days <span aria-hidden="true">⌄</span></span></summary><div class="growth-project-body"><div class="metric-grid">${metric(r.starGain,'Stars gained')}${metric(r.forkGain,'Forks gained')}${metric(r.stars,'Total stars')}${metric(r.forks,'Total forks')}</div><p class="analytics-caption">Measured ${esc(date(r.from))} to ${esc(date(r.to))} (UTC) · Latest check ${esc(new Date(r.to).toLocaleString())} · Trending score ${rate(r.score)}.${r.retryPending?' A later check failed temporarily; this uses the last successful observation.':''}</p><div class="analytics-grid"><div><h4>Stars over time</h4>${chart(r.history,'stars','GitHub stars')}</div><div><h4>Forks over time</h4>${chart(r.history,'forks','GitHub forks')}</div></div><p class="analytics-caption">Lines connect saved observations over the last 35 days. Gaps do not imply daily checks; counts can decrease.</p><details><summary>Saved observations</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Checked (UTC)</th><th>Stars</th><th>Forks</th></tr></thead><tbody>${r.history.map(p=>`<tr><td>${esc(p.at.replace('T',' ').replace(/\.\d+Z$/,' UTC'))}</td><td>${count(p.stars)}</td><td>${count(p.forks)}</td></tr>`).join('')}</tbody></table></div></details><p><a class="button outline" href="/?project=${encodeURIComponent(r.id)}">View listing</a></p></div></details>`}
function render(data){if(!data)return '<section class="analytics-box" id="popularity-growth"><h3>Fastest growing on GitHub</h3><p class="chart-empty">Popularity observations are unavailable.</p></section>';
 const c=data.coverage,sort=data.sort||'trending';return `<section class="analytics-box" id="popularity-growth"><div class="panel-heading growth-heading"><h3>Fastest growing on GitHub</h3><label>Rank by<select id="growth-sort"><option value="trending" ${sort==='trending'?'selected':''}>Trending score</option><option value="stars" ${sort==='stars'?'selected':''}>Stars gained per day</option><option value="forks" ${sort==='forks'?'selected':''}>Forks gained per day</option></select></label></div><p class="analytics-caption">GitHub interest, separate from RepoShelf visitor activity and the visitor date filter. Compares the last successful check with a baseline 1–9 days earlier, aiming for seven days. Only positive growth with a check within 48 hours qualifies.</p><div class="metric-grid">${metric(c.eligible,'Eligible GitHub listings')}${metric(c.observed24h,'Checked within 24 hours')}${metric(c.measured,'With a usable growth window')}${metric(c.growing,'Growing projects')}</div><p class="analytics-caption">Daily observation coverage: ${c.eligible?rate(c.observed24h/c.eligible*100):'0'}%. ${count(c.stale)} stale (over 48 hours), ${count(c.missingObservation)} without a usable latest observation, ${count(c.baselineMissing)} fresh but awaiting a baseline. ${count(c.retryPending)} pending a retry. Updated ${esc(new Date(data.checkedAt).toLocaleString())}.</p><p id="growth-status" class="analytics-caption" role="status"></p>${data.items.length?`<p class="analytics-caption">Showing ${data.items.length} of ${count(data.total)} growing projects. Expand a project to inspect its history.</p><div class="growth-projects">${data.items.map(project).join('')}</div>`:'<p class="chart-empty">No measured positive growth qualifies yet. Daily refreshes will build the history needed; stale counts are excluded.</p>'}<details class="help-reference"><summary>How this score is calculated</summary><p class="analytics-caption">${esc(data.method.score)}. Negative gains are clamped to zero for ranking. Watching counts, RepoShelf likes, visits and payments do not affect the score. These rankings cover visible GitHub listings with usable demos; Spaces are excluded because they use different popularity signals.</p></details></section>`;
}
return {render,chart};
});
